+            const snapshot: {
+                clipId: string;
+                startBeat: number;
+                endBeat: number;
+                midiOffsetBeats?: number;
+            } = {
+                clipId: clip.id,
+                startBeat: clip.startBeat,
+                endBeat: clip.endBeat,
+            };
+            if (clip.midiOffsetBeats !== undefined) {
+                snapshot.midiOffsetBeats = clip.midiOffsetBeats;
+            }
+            return snapshot;
+        });
+        return {
+            trackId: owner.id,
+            eligible: owner.acceptsClipUpdate,
+            clips,
