+function getClipIdentity(
+    identities: readonly ClipReplayIdentity[],
+    identityIndex: number,
+    owner: NormalizedOwner,
+    clip: Clip
+): ClipReplayIdentity | null {
+    const identity = identities[identityIndex];
+    if (!identity) {
+        return null;
