+function planTrack(
+    owner: NormalizedOwner,
+    operation: SelectedTimeRangeOperation,
+    identities: readonly ClipReplayIdentity[],
+    initialIdentityIndex: number,
+    splits: Array<{
+        sourceClipId: string;
+        newClipId: string;
+        splitBeat: number;
+        discardBeforeBeat?: number;
