+                ...clip,
+                endBeat: operation.startBeat,
+                name: `${clip.name} (L)`,
+            };
+            const rightClip: Clip = {
+                ...clip,
+                id: identity.targetClipId,
+                startBeat: operation.endBeat,
+                name: `${clip.name} (R)`,
+                audioOffsetBeats: (clip.audioOffsetBeats ?? 0) + (operation.endBeat - clip.startBeat),
+                midiOffsetBeats: 0,
