+                    newClipId: identity.targetClipId,
+                    splitBeat: operation.endBeat - clip.startBeat + (clip.midiOffsetBeats ?? 0),
+                    discardBeforeBeat: operation.startBeat - clip.startBeat + (clip.midiOffsetBeats ?? 0),
+                });
+            }
