+        trackState,
+        midiOperation: {
+            type: 'delete',
+            startBeat: operation.startBeat,
+            endBeat: operation.endBeat,
+            splits,
+            removeClipIds,
+        },
+    };
+}
+
+function createLocalHandle(input: { capturedState: TrackState; nextState: TrackState }): PreparedHandle {
