+    const midiHandle = asMidiHandle(midiPreparation);
+    const handles: PreparedHandle[] = [];
+    if (midiHandle.hasChanges) {
+        handles.push(midiHandle);
+    }
+    if (localHandle.hasChanges) {
+        handles.push(localHandle);
+    }
+    if (handles.length === 0) {
+        return {
+            status: 'no-change',
+            hasChanges: false,
+            replayPlan,
+        };
+    }
