+    const applied = publishHandles(handles);
+    if (!applied) {
+        return rejectResult();
+    }
+    return {
+        status: 'applied',
+        hasChanges: true,
+        replayPlan,
+        undo: () => undoAppliedHandles(handles),
+    };
