+    const cascade = (async (): Promise<ShutdownOutcome> => {
+        try {
+            return { status: 'completed', report: await shutdown() };
+        } catch (error) {
+            return { status: 'failed', reason: error instanceof Error ? error.message : String(error) };
+        }
